package com.manageinvoice.categories;
import java.util.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import com.manageinvoice.common.security.AuthenticatedUser;
@RestController @RequestMapping("/api/v1/categories") public class CategoryController {private final CategoryService service;public CategoryController(CategoryService service){this.service=service;}@GetMapping public List<Category> list(@AuthenticationPrincipal AuthenticatedUser user,@RequestHeader("X-Workspace-Id") UUID workspaceId){return service.list(workspaceId,user.id());}@PostMapping public Category create(@AuthenticationPrincipal AuthenticatedUser user,@RequestHeader("X-Workspace-Id") UUID workspaceId,@RequestBody CategoryService.CreateRequest request){return service.create(workspaceId,user.id(),request);} }
